<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Theme\Application\Service\Visibility;

use Psr\EventDispatcher\EventDispatcherInterface;

use Iterator;
use Throwable;

use Civi\Lughauth\Features\Access\Tenant\Application\Service\Visibility\TenantVisibilityService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeAttributes;
use Civi\Lughauth\Features\Document\Theme\Domain\Theme;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeFilter;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeCursor;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeReadGateway;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeSlide;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ThemeVisibilityService
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly EventDispatcherInterface $dispatcher,
    private readonly ThemeReadGateway $readGateway,
    private readonly ThemeWriteGateway $writeGateway,
    private readonly TenantVisibilityService $tenantVisibilityService  ) {
  }

  public function prepareVisibleDataInList(Theme $content): ThemeAttributes
  {
    return $this->prepareVisibleDataCallback($content, true);  }
  public function prepareVisibleData(Theme $content): ThemeAttributes
  {
    return $this->prepareVisibleDataCallback($content, false);  }
  public function copyWithFixed(ThemeAttributes $attributes, ?Theme $original = null): ThemeAttributes
  {
    $this->logDebug("Copy with fixed for Theme");
    $span = $this->startSpan("Copy with fixed for  Theme");
    try {
      $visible = $this->visiblesReferences($attributes);
      $fixed = $this->fieldsToFix($original);
      foreach ($fixed as $field) {
        $visible->unset($field);
      }
      $result = $this->dispatcher->dispatch(new ThemePresetValues($attributes, $original));
      return $result->attributes;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }

  public function copyWithHidden(ThemeAttributes $attributes, ?Theme $original = null): ThemeAttributes
  {
    $this->logDebug("Copy with hidden for Theme");
    $span = $this->startSpan("Copy with hidden for  Theme");
    try {
      $hidden = $this->fieldsToHide($original);
      foreach ($hidden as $field) {
        $attributes->unset($field);
      }
      return $attributes;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }

  public function checkVisibility(Iterator|string|ThemeRef $value): bool
  {
    $this->logDebug("Check visibility of an iterator for Theme");
    $span = $this->startSpan("Check visibility of an iterator for  Theme");
    try {
      if (is_string($value)) {
        return !!$this->retrieveVisibleForUpdate(new ThemeRef( $value ) );
      } else if ($value instanceof ThemeRef) {
        return !!$this->retrieveVisibleForUpdate($value );
      } else if ($value instanceof Iterator) {
        $ids = [];
        foreach ($value as $val) {
          $ids[] = $val->uid();
        }
        $filter = new ThemeFilter(uids: $ids);
        return count($ids) == $this->countVisibles($filter);
      } else {        return false;      }
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function listVisibles(ThemeFilter $filter, ?ThemeCursor $cursor = null): ThemeSlide
  {
    $this->logDebug("List visibles for Theme");
    $span = $this->startSpan("List visibles for  Theme");
    try {
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      $result = $this->readGateway->list($visibleFilter, $cursor);
      return $result->slide(function(Theme $item): bool {
        return $this->evaluatePostVisibility($item);
      });
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function countVisibles(ThemeFilter $filter): int
  {
    $this->logDebug("Count visibles for Theme");
    $span = $this->startSpan("Count visibles for  Theme");
    try {
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      return $this->readGateway->count($visibleFilter);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function listVisiblesForUpdate(ThemeFilter $filter, ?ThemeCursor $cursor = null): ThemeSlide
  {
    $this->logDebug("List visibles for update for Theme");
    $span = $this->startSpan("List visibles for update for  Theme");
    try {
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
      return $result->slide(function(Theme $item): bool {
        return $this->evaluatePostVisibility($item);
      });
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function countVisiblesForUpdate(ThemeFilter $filter): int
  {
    $this->logDebug("Count visibles for update for Theme");
    $span = $this->startSpan("Count visibles for update for  Theme");
    try {
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      return $this->writeGateway->countForUpdate($visibleFilter);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function retrieveVisible(ThemeRef $ref): ?Theme
  {
    $this->logDebug("Retrieve visible for Theme");
    $span = $this->startSpan("Retrieve visible for  Theme");
    try {
      $filter = new ThemeFilter(uids: [$ref->uid()]);
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      if ($readed = $this->readGateway->retrieve($visibleFilter)) {
        return $this->evaluatePostVisibility($readed) ? $readed : null;
      } else {
        return null;
      }
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function retrieveVisibleForUpdate(ThemeRef $ref): ?Theme
  {
    $this->logDebug("Retrieve visible for update for Theme");
    $span = $this->startSpan("Retrieve visible for update for  Theme");
    try {
      $filter = new ThemeFilter(uids: [$ref->uid()]);
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      if( $readed = $this->writeGateway->retrieveForUpdate($visibleFilter) ) {
        return $this->evaluatePostVisibility($readed) ? $readed : null;
      } else {
        return null;
      }
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function fieldsToFix(?ThemeRef $ref = null): array
  {
    $this->logDebug("Check fields to fix for Theme");
    $span = $this->startSpan("Check fields for fix for Theme");
    try {
      $result = $this->dispatcher->dispatch(new ThemeCollectNonEditableFields(Theme::calculatedFields(), $ref));
      return array_values( array_unique( array_merge( $this->fieldsToHide($ref), $result->fields) ) );
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }

  public function fieldsToHide(?ThemeRef $ref = null): array
  {
    $this->logDebug("Check fields to hide for Theme");
    $span = $this->startSpan("Check fields to hide for  Theme");
    try {
      $result = $this->dispatcher->dispatch(new ThemeCollectNonVisibleFields([], $ref));
      return array_values( array_unique( $result->fields ) );
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }

  private function visiblesReferences(ThemeAttributes $attributes): ThemeAttributes
  {
    $this->logDebug("Check visibility of parent references for Theme");
    $span = $this->startSpan("Check visibility of parent references for  Theme");
    try {
      $tenant = $attributes->getTenant();      if( null !== $tenant && !$this->tenantVisibilityService->checkVisibility($tenant) ) {
        throw new NotFoundException("Unknown Tenant " . ( $tenant->uid() ?? 'no-id'));
      }
      return $attributes;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  private function applyPreVisibilityFilter(ThemeFilter $filter): ThemeFilter
  {
    $this->logDebug("Compose visibility filter for Theme");
    $span = $this->startSpan("Compose visibility filter for  Theme");
    try {
      $result = $this->dispatcher->dispatch(new ThemeRestrictFilterToVisibility($filter));
      return $result->themeFilter;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  private function evaluatePostVisibility(Theme $value): bool
  {
    $this->logDebug("Check if item is visible for Theme");
    $span = $this->startSpan("Check if item is visible for  Theme");
    try {
      $result = $this->dispatcher->dispatch(new ThemeVisibilityCheck(true, $value));
      return $result->visible;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  private function prepareVisibleDataCallback(Theme $content, bool $inlist): ThemeAttributes
  {
    $this->logDebug("Prepare hydration to visible data for Theme");
    $span = $this->startSpan("Prepare hydration to visible data for Theme");
    try {
      $attributes = $content->toAttributes();      $result = $this->dispatcher->dispatch(new ThemeEnrichForView($content, $inlist, $attributes));
      return $result->getAttributes();
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
